package studio.scenecam.probe;
import android.media.*;
import android.opengl.*;
import android.view.Surface;
import android.graphics.Bitmap;
import java.io.*;
import java.nio.ByteBuffer;
/** Verifies the same OES draw survives a real AVC/MP4 encoding and decoding pass. */
final class RoundGridEncoder {
 private final MediaCodec codec;private final MediaMuxer muxer;private final Surface input;private final EGLDisplay display;private final EGLSurface output;private int track=-1;private final File file;
 RoundGridEncoder(File file)throws Exception{this.file=file;MediaFormat format=MediaFormat.createVideoFormat("video/avc",400,400);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);format.setInteger(MediaFormat.KEY_BIT_RATE,2000000);format.setInteger(MediaFormat.KEY_FRAME_RATE,15);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);codec=MediaCodec.createEncoderByType("video/avc");codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);input=codec.createInputSurface();codec.start();muxer=new MediaMuxer(file.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);display=EGL14.eglGetCurrentDisplay();int[] id=new int[1],count=new int[1];EGL14.eglQueryContext(display,EGL14.eglGetCurrentContext(),EGL14.EGL_CONFIG_ID,id,0);EGLConfig[] config=new EGLConfig[1];EGL14.eglChooseConfig(display,new int[]{EGL14.EGL_CONFIG_ID,id[0],EGL14.EGL_NONE},0,config,0,1,count,0);output=EGL14.eglCreateWindowSurface(display,config[0],input,new int[]{EGL14.EGL_NONE},0);if(output==EGL14.EGL_NO_SURFACE)throw new IOException("encoder EGL surface "+EGL14.eglGetError());}
 void frame(long ns)throws Exception{EGLContext context=EGL14.eglGetCurrentContext();EGLSurface draw=EGL14.eglGetCurrentSurface(EGL14.EGL_DRAW),read=EGL14.eglGetCurrentSurface(EGL14.EGL_READ);try{if(!EGL14.eglMakeCurrent(display,output,output,context))throw new IOException("encoder makeCurrent");GLES20.glViewport(0,0,400,400);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);EGLExt.eglPresentationTimeANDROID(display,output,ns);if(!EGL14.eglSwapBuffers(display,output))throw new IOException("encoder swap");}finally{EGL14.eglMakeCurrent(display,draw,read,context);}drain(false);}
 private void drain(boolean end)throws Exception{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();for(int tries=0;tries<200;tries++){int index=codec.dequeueOutputBuffer(info,end?10000:0);if(index==MediaCodec.INFO_TRY_AGAIN_LATER){if(!end)return;continue;}if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=muxer.addTrack(codec.getOutputFormat());muxer.start();continue;}if(index>=0){ByteBuffer data=codec.getOutputBuffer(index);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0){data.position(info.offset);data.limit(info.offset+info.size);muxer.writeSampleData(track,data,info);}boolean done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(index,false);if(done)return;}}throw new IOException("encoder EOS timeout");}
 void finish()throws Exception{try{codec.signalEndOfInputStream();drain(true);}finally{codec.stop();codec.release();if(track>=0)muxer.stop();muxer.release();EGL14.eglDestroySurface(display,output);input.release();}try(MediaMetadataRetriever retriever=new MediaMetadataRetriever()){retriever.setDataSource(file.getPath());Bitmap b=retriever.getFrameAtTime(0);if(b==null)throw new IOException("No decoded AVC frame");try(FileOutputStream out=new FileOutputStream(new File(file.getParentFile(),file.getName()+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}}
}
